// ============================================================================
// WATCH MANAGEMENT
// ============================================================================

bool webdav_push_watch_add(const char* path, bool recursive, WebDAVPushEventType event_mask) {
    if (!g_initialized || !path || g_config.watch_count >= WEBDAV_PUSH_MAX_WATCHED_PATHS) {
        return false;
    }
    
    // Check if already watching
    for (int i = 0; i < g_config.watch_count; i++) {
        if (strcmp(g_config.watches[i].path, path) == 0) {
            return true;  // Already watching
        }
    }
    
    // Add new watch
    WebDAVPushWatchConfig* watch = &g_config.watches[g_config.watch_count++];
    watch->enabled = true;
    watch->recursive = recursive;
    watch->event_mask = event_mask;
    
    strncpy(watch->path, path, sizeof(watch->path) - 1);
    watch->path[sizeof(watch->path) - 1] = '\0';
    
    return true;
}

bool webdav_push_watch_remove(const char* path) {
    if (!g_initialized || !path) {
        return false;
    }
    
    for (int i = 0; i < g_config.watch_count; i++) {
        if (strcmp(g_config.watches[i].path, path) == 0) {
            g_config.watches[i].enabled = false;
            // Compact array
            for (int j = i; j < g_config.watch_count - 1; j++) {
                g_config.watches[j] = g_config.watches[j + 1];
            }
            g_config.watch_count--;
            return true;
        }
    }
    
    return false;
}

bool webdav_push_watch_is_watched(const char* path) {
    if (!g_initialized || !path) {
        return false;
    }
    
    for (int i = 0; i < g_config.watch_count; i++) {
        if (g_config.watches[i].enabled) {
            if (strcmp(g_config.watches[i].path, path) == 0) {
                return true;
            }
            // Check if path starts with watched path
            if (g_config.watches[i].recursive && 
                strncmp(path, g_config.watches[i].path, strlen(g_config.watches[i].path)) == 0) {
                return true;
            }
        }
    }
    
    return false;
}

void webdav_push_check_changes(void) {
    if (!g_initialized || !g_config.enabled) {
        return;
    }
    
    for (int i = 0; i < g_config.watch_count; i++) {
        if (g_config.watches[i].enabled) {
            check_watched_path(&g_config.watches[i]);
        }
    }
}

