/// @brief Convert event type to string
const char* webdav_push_event_to_string(WebDAVPushEventType type) {
    static const char* EVENT_NAMES[] = {
        "file_created",
        "file_modified", 
        "file_deleted",
        "file_moved",
        "folder_created",
        "folder_deleted",
        "project_updated",
        "gui_updated",
        "system_event",
        "custom"
    };
    
    if (type < sizeof(EVENT_NAMES) / sizeof(EVENT_NAMES[0])) {
        return EVENT_NAMES[type];
    }
    return "unknown";
}

/// @brief Convert notification to JSON string
static const char* webdav_push_notification_to_json(const WebDAVPushNotification* notification) {
    static char json_buffer[512];
    
    if (!notification) {
        return "{}";
    }
    
    char escaped_path[WEBDAV_PUSH_MAX_PATH * 2];
    char escaped_old_path[WEBDAV_PUSH_MAX_PATH * 2];
    
    // Simple JSON escaping (for demo)
    escape_json_string(notification->path, escaped_path, sizeof(escaped_path));
    escape_json_string(notification->old_path, escaped_old_path, sizeof(escaped_old_path));
    
    snprintf(json_buffer, sizeof(json_buffer),
        "{\"type\":\"%s\",\"timestamp\":%llu,\"path\":\"%s\",\"old_path\":\"%s\",\"size\":%u,\"custom\":\"%s\"}",
        webdav_push_event_to_string(notification->type),
        notification->timestamp,
        escaped_path[0] ? escaped_path : "",
        escaped_old_path[0] ? escaped_old_path : "",
        notification->size,
        notification->custom_data[0] ? notification->custom_data : "");
    
    return json_buffer;
}

/// @brief Simple JSON string escaping
static void escape_json_string(const char* input, char* output, size_t output_size) {
    if (!input || !output || output_size == 0) {
        if (output && output_size > 0) {
            output[0] = '\0';
        }
        return;
    }
    
    size_t pos = 0;
    for (size_t i = 0; input[i] != '\0' && pos < output_size - 1; i++) {
        switch (input[i]) {
            case '"': output[pos++] = '\\'; if (pos < output_size - 1) output[pos++] = '"'; break;
            case '\\': output[pos++] = '\\'; if (pos < output_size - 1) output[pos++] = '\\'; break;
            case '\b': output[pos++] = '\\'; if (pos < output_size - 1) output[pos++] = 'b'; break;
            case '\f': output[pos++] = '\\'; if (pos < output_size - 1) output[pos++] = 'f'; break;
            case '\n': output[pos++] = '\\'; if (pos < output_size - 1) output[pos++] = 'n'; break;
            case '\r': output[pos++] = '\\'; if (pos < output_size - 1) output[pos++] = 'r'; break;
            case '\t': output[pos++] = '\\'; if (pos < output_size - 1) output[pos++] = 't'; break;
            default: output[pos++] = input[i]; break;
        }
    }
    output[pos] = '\0';
}

// ============================================================================
// SSE IMPLEMENTATION
// ============================================================================

const char* webdav_push_sse_stream(uint32_t client_id) {
    static char sse_header[256];
    
    if (!g_initialized || !g_config.use_sse) {
        return NULL;
    }
    
    WebDAVPushClient* client = webdav_push_client_get(client_id);
    if (!client || client->type != WEBDAV_PUSH_CLIENT_SSE) {
        return NULL;
    }
    
    // Return SSE headers
    snprintf(sse_header, sizeof(sse_header),
        "HTTP/1.1 200 OK\r\n"
        "Content-Type: text/event-stream\r\n"
        "Cache-Control: no-cache\r\n"
        "Connection: keep-alive\r\n"
        "Access-Control-Allow-Origin: *\r\n"
        "\r\n");
    
    return sse_header;
}

void webdav_push_sse_send_event(uint32_t client_id, const char* event_type, const char* data) {
    if (!g_initialized || !g_config.use_sse || !event_type) {
        return;
    }
    
    WebDAVPushClient* client = webdav_push_client_get(client_id);
    if (!client || !client->active || client->type != WEBDAV_PUSH_CLIENT_SSE) {
        return;
    }
    
    // Format: "event: <type>\ndata: <data>\n\n"
    static char sse_message[1024];
    snprintf(sse_message, sizeof(sse_message),
        "event: %s\ndata: %s\n\n",
        event_type,
        data ? data : "{}");
    
    // In real implementation, send to client connection
    // For demo, we just format the message
    (void)sse_message;
}

// ============================================================================
// WEBSOCKET IMPLEMENTATION
// ============================================================================

bool webdav_push_websocket_connect(uint32_t client_id) {
    if (!g_initialized || !g_config.use_websocket) {
        return false;
    }
    
    WebDAVPushClient* client = webdav_push_client_get(client_id);
    if (!client || !client->active) {
        return false;
    }
    
    client->type = WEBDAV_PUSH_CLIENT_WEBSOCKET;
    return true;
}

void webdav_push_websocket_disconnect(uint32_t client_id) {
    if (!g_initialized) {
        return;
    }
    
    WebDAVPushClient* client = webdav_push_client_get(client_id);
    if (client && client->active && client->type == WEBDAV_PUSH_CLIENT_WEBSOCKET) {
        client->active = false;
    }
}

void webdav_push_websocket_send(uint32_t client_id, const char* message) {
    if (!g_initialized || !g_config.use_websocket || !message) {
        return;
    }
    
    WebDAVPushClient* client = webdav_push_client_get(client_id);
    if (!client || !client->active || client->type != WEBDAV_PUSH_CLIENT_WEBSOCKET) {
        return;
    }
    
    // In real implementation, send WebSocket message
    // For demo, we just acknowledge
    (void)message;
}

// ============================================================================
// LONG POLLING IMPLEMENTATION
// ============================================================================

const char* webdav_push_long_poll(uint32_t client_id) {
    if (!g_initialized || !g_config.use_long_poll) {
        return "[]";
    }
    
    WebDAVPushClient* client = webdav_push_client_get(client_id);
    if (!client || !client->active || client->type != WEBDAV_PUSH_CLIENT_LONG_POLL) {
        return "[]";
    }
    
    // Check if we have queued notifications
    if (g_long_poll_has_notification[client_id - 1]) {
        // Format as JSON array
        static char json_response[2048];
        snprintf(json_response, sizeof(json_response), "[%s]",
                webdav_push_notification_to_json(&g_long_poll_queues[client_id - 1]));
        g_long_poll_has_notification[client_id - 1] = false;
        return json_response;
    }
    
    return "[]";  // Empty array
}

void webdav_push_long_poll_queue(uint32_t client_id, const WebDAVPushNotification* notification) {
    if (!g_initialized || !g_config.use_long_poll || !notification) {
        return;
    }
    
    WebDAVPushClient* client = webdav_push_client_get(client_id);
    if (!client || !client->active || client->type != WEBDAV_PUSH_CLIENT_LONG_POLL) {
        return;
    }
    
    // Queue notification (overwrite previous for simplicity)
    if (client_id > 0 && client_id <= WEBDAV_PUSH_MAX_CLIENTS) {
        g_long_poll_queues[client_id - 1] = *notification;
        g_long_poll_has_notification[client_id - 1] = true;
    }
}
